input.content:
:root {
  --bg: #07191e;
  --bg2: #0d2e34;
  --panel: rgba(8, 17, 20, 0.78);
  --panel-strong: rgba(9, 18, 22, 0.92);
  --panel-alt: rgba(13, 32, 34, 0.8);
  --border: rgba(162, 208, 214, 0.2);
  --text: #ebf4f4;
  --muted: #a9c1c5;
  --primary: #8ce8d6;
  --primary-strong: #4edec1;
  --warning: #ffcf70;
  --alert: #ff7d6b;
  --shadow: rgba(5, 13, 14, 0.5);
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: Inter, "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top, rgba(67, 109, 118, 0.4), transparent 35%),
    linear-gradient(145deg, #050b0d 0%, #0a1718 20%, #081b1f 100%);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
button, input {
  font: inherit;
}
.app-shell {
  width: min(1180px, 100%);
  display: grid;
  gap: 18px;
}
.topbar, .journey-strip, .controls-card, .view-card, footer {
  background: var(--panel);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  box-shadow: 0 18px 35px rgba(0,0,0,0.18);
}
.topbar {
  border-radius: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--text);
}
.brand-mark {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary), #b7fff3);
  color: #092325;
  font-weight: 900;
  font-size: 1.3rem;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.35);
}
.brand-mark span { font-size: 0.7rem; }
.brand > span:last-child {
  display: flex;
  flex-direction: column;
  line-height: 1;
  letter-spacing: 0.12em;
}
.brand > span:last-child b { font-size: 0.9rem; }
.brand > span:last-child small { font-size: 0.62rem; color: var(--muted); }
.route-heading {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding-inline: 12px;
}
.route-heading h1 {
  margin: 0;
  font-weight: 800;
  letter-spacing: 0.03em;
  font-size: clamp(1.05rem, 2vw, 2rem);
}
.route-heading h1 span { color: var(--primary); }
.eyebrow {
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.62rem;
  color: var(--muted);
}
.top-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.live-pill {
  border-radius: 999px;
  background: rgba(95, 220, 186, 0.12);
  border: 1px solid rgba(126, 241, 211, 0.3);
  color: var(--primary);
  padding: 8px 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.live-pill i {
  width: 8px; height: 8px; border-radius: 50%; background: var(--primary); display: block; box-shadow: 0 0 12px rgba(76, 238, 206, 0.8);
}
.icon-button, .help-button, .primary-button, .direction-button, .horn-button, .close-button {
  border: 1px solid var(--border);
  background: rgba(95, 122, 126, 0.12);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.15s ease;
}
.icon-button:hover, .help-button:hover, .primary-button:hover, .direction-button:hover, .horn-button:hover, .close-button:hover { transform: translateY(-1px); }
.icon-button {
  width: 42px; height: 42px; border-radius: 12px;
  font-size: 1.1rem;
}
.view-card {
  position: relative;
  overflow: hidden;
  min-height: 470px;
  border-radius: 28px;
}
#scene {
  width: 100%;
  height: 470px;
  display: block;
  background: linear-gradient(180deg, #7bb8d9, #dfe9ee 18%, #b9d3b7 18%, #8cb982 100%);
}
.view-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0.17), rgba(0,0,0,0.0) 40%, rgba(0,0,0,0.1));
  pointer-events: none;
}
.scene-topline, .scene-bottomline, .signal-chip {
  position: absolute;
  z-index: 2;
}
.scene-topline {
  top: 18px; left: 18px; right: 18px; display: flex; justify-content: space-between; align-items: center;
  color: rgba(255,255,255,0.9);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.location { display: inline-flex; align-items: center; gap: 8px; }
.location-dot {
  width: 10px; height: 10px; border-radius: 50%; background: var(--primary); box-shadow: 0 0 16px rgba(128, 241, 218, 0.92);
}
.weather { display: inline-flex; align-items: center; gap: 8px; }
.weather-divider { opacity: 0.5; }
.signal-chip {
  left: 24px; bottom: 54px;
  background: rgba(9, 20, 23, 0.74);
  border: 1px solid rgba(165, 203, 208, 0.2);
  border-radius: 16px;
  padding: 10px 14px;
  display: flex; align-items: center; gap: 12px;
  box-shadow: 0 14px 28px rgba(0,0,0,0.2);
}
.signal-lamp {
  width: 14px; height: 14px; border-radius: 50%; background: var(--primary); display: block; box-shadow: 0 0 0 6px rgba(123, 255, 214, 0.12), 0 0 25px rgba(123, 255, 214, 0.65);
}
.signal-chip b { display: block; font-size: 0.78rem; letter-spacing: 0.12em; }
.signal-chip small { display: block; color: var(--muted); letter-spacing: 0.08em; }
.scene-bottomline {
  right: 20px; bottom: 20px; left: 20px;
  display: flex; justify-content: space-between;
  color: rgba(244,255,255,0.9);
  letter-spacing: 0.15em; font-size: 0.7rem; text-transform: uppercase;
}
.toast {
  position: absolute; left: 50%; bottom: 76px; transform: translateX(-50%) translateY(12px); opacity: 0; z-index: 4;
  background: rgba(9, 20, 23, 0.88); border: 1px solid rgba(163, 209, 214, 0.2); color: var(--text); padding: 10px 16px; border-radius: 999px; font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; transition: all 0.25s ease;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.overlay {
  position: absolute; inset: 0; display: grid; place-items: center; background: rgba(4, 10, 13, 0.64); backdrop-filter: blur(4px); z-index: 5;
}
.overlay.hidden, .dialog-backdrop.hidden { display: none; }
.overlay-card, .help-dialog {
  width: min(430px, calc(100% - 32px));
  background: rgba(9, 20, 23, 0.92);
  border: 1px solid rgba(160, 207, 212, 0.2);
  border-radius: 26px;
  padding: 24px 22px 18px;
  box-shadow: 0 22px 36px rgba(0,0,0,0.25);
}
.overlay-card { text-align: center; }
.overlay-icon {
  display: grid; place-items: center; width: 58px; height: 58px; margin: 0 auto 12px; border-radius: 18px; background: rgba(105, 234, 211, 0.1); color: var(--primary); font-size: 1.6rem; font-weight: 800;
}
.finish-icon { background: rgba(255, 204, 103, 0.1); color: var(--warning); }
.overlay-card h2, .help-dialog h2 { margin: 8px 0 8px; font-size: clamp(1.8rem, 2vw, 2.5rem); }
.overlay-card p, .help-dialog p { margin: 0; color: var(--muted); line-height: 1.5; }
.final-score {
  margin: 20px 0 18px; display: flex; justify-content: space-between; align-items: center; padding: 12px 14px; border-radius: 14px; background: rgba(255,255,255,0.03); border: 1px solid rgba(163, 213, 218, 0.15);
}
.final-score span { letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); font-size: 0.62rem; }
.final-score b { font-size: clamp(1.5rem, 2vw, 2.2rem); }
.primary-button {
  border-radius: 14px; padding: 0.9rem 1.3rem; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; background: linear-gradient(135deg, rgba(90, 236, 211, 0.9), rgba(138, 223, 255, 0.7)); color: #082226; border: none; box-shadow: 0 16px 30px rgba(75, 219, 193, 0.2);
}
.primary-button span { font-size: 1.1rem; }
.journey-strip {
  border-radius: 22px; padding: 18px 18px 14px; display: grid; grid-template-columns: minmax(0, 1.75fr) auto auto; gap: 16px; align-items: center;
}
.journey-main { display: flex; flex-direction: column; gap: 8px; }
.journey-title { display: flex; flex-direction: column; gap: 6px; }
.journey-title b { font-size: clamp(1.1rem, 2vw, 1.5rem); }
.progress-wrap { display: grid; gap: 8px; }
.progress-label {
  display: flex; justify-content: space-between; gap: 10px; font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted);
}
.progress-track {
  position: relative; height: 12px; border-radius: 99px; background: rgba(155, 201, 206, 0.12); overflow: hidden; border: 1px solid rgba(155, 201, 206, 0.18);
}
.progress-fill {
  position: absolute; inset: 0 auto 0 0; width: 0%; border-radius: 99px; background: linear-gradient(90deg, rgba(115, 234, 201, 0.65), rgba(103, 141, 255, 0.82));
}
.progress-marker { position: absolute; top: 50%; left: 0; width: 18px; height: 18px; border-radius: 50%; background: white; border: 3px solid var(--primary-strong); box-shadow: 0 0 0 3px rgba(109, 233, 204, 0.25); transform: translate(-50%, -50%); }
.score-block, .limit-block {
  min-width: 133px; padding: 10px 14px; border-radius: 16px; background: rgba(255,255,255,0.02); border: 1px solid rgba(163, 213, 218, 0.12);
}
.score-block span, .limit-block span { color: var(--muted); }
.score-block div, .limit-block div {
  display: flex; align-items: baseline; gap: 6px; margin-top: 6px;
}
.score-block b, .limit-block b { font-size: clamp(1.3rem, 2vw, 2rem); }
.score-block span:last-child, .limit-block span:last-child { font-size: 0.72rem; letter-spacing: 0.1em; }
.controls-card {
  border-radius: 24px; padding: 18px;
}
.controls-heading {
  display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 16px;
}
.controls-heading h2 {
  margin: 8px 0 0; font-size: clamp(1.2rem, 2vw, 1.8rem);
}
.help-button {
  border-radius: 12px; padding: 0.75rem 1rem; display: inline-flex; align-items: center; gap: 8px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; font-size: 0.7rem; color: var(--muted);
}
.help-button span { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; background: rgba(255,255,255,0.06); color: var(--text); font-weight: 800; }
.control-grid {
  display: grid;
  grid-template-columns: 1.3fr 1.3fr minmax(180px, 0.8fr) minmax(180px, 0.9fr);
  gap: 16px;
}
.drive-control {
  background: rgba(255,255,255,0.025); border: 1px solid rgba(163, 213, 218, 0.12); border-radius: 20px; padding: 16px 16px 14px; display: flex; flex-direction: column; gap: 12px;
}
.control-label {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
}
.control-label > span:first-child { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 12px; border: 1px solid rgba(163, 213, 218, 0.2); }
.control-label > span:nth-child(2) { display: flex; flex-direction: column; flex: 1; }
.control-label b { font-size: 0.82rem; letter-spacing: 0.12em; }
.control-label small { display: block; color: var(--muted); letter-spacing: 0.08em; }
.control-label strong {
  font-size: 1.4rem; color: var(--primary); font-weight: 800;
}
.control-label strong span { font-size: 0.74rem; opacity: 0.85; }
.range {
  width: 100%; -webkit-appearance: none; appearance: none; background: transparent; height: 28px;
}
.range:focus { outline: none; }
.range::-webkit-slider-runnable-track {
  height: 8px; border-radius: 999px; background: linear-gradient(90deg, rgba(101, 209, 187, 0.8), rgba(143, 157, 255, 0.4));
}
.range::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none; width: 20px; height: 20px; border-radius: 50%; background: #eaf9ff; border: 3px solid var(--primary-strong); margin-top: -6px; box-shadow: 0 0 0 4px rgba(93, 227, 191, 0.15);
}
.range::-moz-range-track { height: 8px; border-radius: 999px; background: linear-gradient(90deg, rgba(101, 209, 187, 0.8), rgba(143, 157, 255, 0.4)); }
.range::-moz-range-thumb { width: 20px; height: 20px; border-radius: 50%; background: #eaf9ff; border: 3px solid var(--primary-strong); box-shadow: 0 0 0 4px rgba(93, 227, 191, 0.15); }
.range-ticks {
  display: flex; justify-content: space-between; font-size: 0.56rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted);
}
.speed-dial {
  background: linear-gradient(180deg, rgba(14, 30, 33, 0.85), rgba(10, 21, 24, 0.9)); border: 1px solid rgba(163, 213, 218, 0.1); border-radius: 20px; padding: 18px 16px; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; gap: 8px;
}
.speed-dial > div {
  display: flex; align-items: baseline; gap: 5px; justify-content: center;
}
.speed-dial b { font-size: clamp(2.4rem, 5vw, 4rem); line-height: 1; }
.speed-dial span { color: var(--muted); font-size: 1.05rem; }
.speed-dial small { letter-spacing: 0.12em; text-transform: uppercase; color: var(--primary); font-size: 0.7rem; }
.small-controls {
  display: flex; flex-direction: column; gap: 12px;
}
.direction-button, .horn-button {
  border-radius: 18px; padding: 14px 16px; display: flex; align-items: center; justify-content: space-between; gap: 12px; text-align: left; width: 100%;
}
.direction-icon { font-size: 1.4rem; color: var(--primary); }
.direction-button b, .horn-button b { display: block; letter-spacing: 0.12em; }
.direction-button small, .horn-button small { display: block; color: var(--muted); letter-spacing: 0.08em; }
.chevrons { color: var(--muted); font-size: 0.9rem; line-height: 0.9; }
.horn-button {
  justify-content: flex-start; gap: 10px;
}
.horn-button span { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; background: rgba(255, 189, 92, 0.12); color: var(--warning); font-weight: 800; }
.tip-row {
  margin-top: 16px; padding: 12px 14px; border-radius: 14px; background: rgba(255,255,255,0.02); border: 1px solid rgba(163, 213, 218, 0.12); display: flex; align-items: center; gap: 10px; justify-content: space-between; color: var(--muted); font-size: 0.73rem; line-height: 1.4;
}
.tip-spark { color: var(--warning); }
.keyboard-tip { color: var(--text); opacity: 0.72; }
.keyboard-tip kbd { border-radius: 8px; padding: 3px 7px; border: 1px solid rgba(163, 213, 218, 0.22); background: rgba(255,255,255,0.04); font-family: inherit; }
footer {
  border-radius: 18px; padding: 12px 18px; display: flex; justify-content: space-between; gap: 10px; color: var(--muted); font-size: 0.68rem; letter-spacing: 0.12em; text-transform: uppercase;
}
.footer-dot { color: var(--primary); }
.dialog-backdrop {
  position: fixed; inset: 0; z-index: 9; background: rgba(5, 10, 12, 0.64); display: grid; place-items: center; padding: 16px;
}
.help-dialog {
  position: relative;
}
.close-button {
  position: absolute; top: 14px; right: 14px; width: 34px; height: 34px; border-radius: 10px; font-size: 1.4rem; line-height: 1; }
.help-dialog p { margin-top: 10px; }
.help-steps { display: grid; gap: 12px; margin: 18px 0; }
.help-steps > div {
  display: grid; grid-template-columns: 40px 1fr; gap: 12px; align-items: start; padding: 12px 10px; border-radius: 14px; background: rgba(255,255,255,0.02); border: 1px solid rgba(163,213,218,0.08);
}
.help-steps i {
  width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; background: rgba(116, 239, 196, 0.12); color: var(--primary); font-style: normal; font-weight: 800;
}
.help-steps b { display: block; margin-bottom: 4px; }
.help-steps small { color: var(--muted); }
.keyboard-note { color: var(--text); opacity: 0.8; }
@media (max-width: 900px) {
  .journey-strip { grid-template-columns: 1fr; }
  .control-grid { grid-template-columns: 1fr 1fr; }
  .speed-dial { min-height: 160px; }
}
@media (max-width: 620px) {
  body { padding: 12px; }
  .topbar { flex-wrap: wrap; }
  .route-heading { order: 3; width: 100%; padding-inline: 0; }
  .top-actions { margin-left: auto; }
  .control-grid { grid-template-columns: 1fr; }
  .view-card { min-height: 380px; }
  #scene { height: 380px; }
  .scene-topline, .scene-bottomline { font-size: 0.6rem; letter-spacing: 0.11em; }
  .signal-chip { left: 16px; bottom: 50px; }
  footer { flex-direction: column; align-items: flex-start; }
  .tip-row { flex-direction: column; align-items: flex-start; }
}
